<template>
  <view class="pilot">
    <view class="top"><text class="brand">△ 三角 · 找队友</text><text class="badge">两人组队</text></view>
    <view class="hero-pilot"><view><text class="eyebrow">找目标一致的队友</text><view class="headline">先说好怎么玩，<br/><text>再一起出发。</text></view><view class="intro">烽火地带 · 找到合拍的队友<br/>目标、装备预算、实力预期，一次对齐。</view></view></view>
    <view class="tabs"><button v-for="t in ['本局条件','招募大厅','我的组局']" :key="t" :class="{active:tab===t}" @click="switchTab(t)">{{t}}</button></view>
    <view v-if="error" class="error" role="alert">{{error}}</view><view v-if="state.notice" class="notice">{{state.notice}}</view><view v-if="state.squad?.status==='proposed' && tab!=='我的组局'" class="warning">有待确认的队友，剩余 {{confirmRemaining}} 秒。<button class="btn-secondary" @click="switchTab('我的组局')">查看本局约定</button></view>
    <view v-if="tab==='本局条件'" class="layout">
      <view class="panel-pilot"><view class="small local-note">条件会保存在当前浏览器，方便下次复用。</view><view v-if="localSaveFailed" class="warning">浏览器暂时无法保存资料，你仍可继续使用，但刷新后可能需要重新填写。</view><view class="section-num">01 / 先确认能一起玩</view><view class="form-grid">
        <label>队内昵称<input v-model="form.nickname" maxlength="24" placeholder="怎么称呼你"/></label>
        <label>游戏 ID<input v-model="form.game_id" maxlength="64" placeholder="双方确认后向队友展示"/></label>
        <label v-for="field in fields" :key="field.key">{{field.label}}<picker :range="field.values" :value="field.values.indexOf(form[field.key])" @change="form[field.key]=field.values[Number($event.detail.value)]"><view class="select">{{form[field.key]}} <text>⌄</text></view></picker></label>
      </view>
      <view class="section-num divider">02 / 这次想怎么玩</view><view class="choices"><button v-for="g in goals" :key="g" :class="{chosen:form.goal===g}" @click="form.goal=g">{{g}}</button></view><view class="small">{{goalNotes[form.goal]}}</view>
      <view class="form-grid divider"><label>装备预算下限（万游戏币）<input v-model.number="form.budget_min" type="number"/></label><label>装备预算上限（万游戏币）<input v-model.number="form.budget_max" type="number"/></label></view><view class="small">填写本局愿意携带的装备价值范围。</view>
      <view class="section-num divider">03 / 你接受什么实力差距</view><label>当前段位<picker :range="ranks" :value="form.rank-1" @change="form.rank=Number($event.detail.value)+1"><view class="select">{{ranks[form.rank-1]}} ⌄</view></picker></label>
      <label>对应地图与难度的自评水平<picker :range="skills" :value="form.skill-1" @change="form.skill=Number($event.detail.value)+1"><view class="select">{{skills[form.skill-1]}} ⌄</view></picker></label><view class="small">{{skillNotes[form.skill-1]}}</view>
      <label>可接受相差几档<picker :range="gaps" :value="form.gap" @change="form.gap=Number($event.detail.value)"><view class="select">{{gaps[form.gap]}} ⌄</view></picker></label>
      <view class="section-num divider">04 / 选择找队友的方式</view><view class="choices"><button :class="{chosen:form.discovery==='browse'}" @click="form.discovery='browse'">看推荐，自己挑</button><button :class="{chosen:form.discovery==='auto'}" @click="form.discovery='auto'">系统自动找</button></view><view class="small">自己挑选队友，或让系统帮你寻找。</view><label class="public-choice">公开我的本局招募<switch :checked="form.public" @change="form.public=$event.detail.value" color="#286952"/></label><view class="small">让其他玩家在大厅看到你的组队需求。游戏 ID 仅在双方确认后展示。</view><button class="btn-primary submit" :disabled="busy || activeTicket" @click="join">{{activeTicket?'已有组局，可去大厅或「我的组局」':'提交条件，寻找一位队友'}}</button>
      </view>
      <view class="aside"><view class="panel-pilot"><text class="eyebrow">先把预期说清楚</text><view class="aside-title">不是每个人，<br/>都在找同一种局。</view><view class="rule"><b>目标一致</b><view>不让任务玩家和主动找架的玩家互相失望。</view></view><view class="rule"><b>预算有交集</b><view>让装备投入先有共识，减少临时分歧。</view></view><view class="rule"><b>双方接受差距</b><view>按更严格的一方要求匹配，不暗中放宽。</view></view></view></view>
    </view>
    <view v-if="tab==='招募大厅'">
      <view v-if="state.ticket && !activeTicket" class="notice">{{state.ticket.status==='expired'?'你的招募已过期，重新发布后即可申请组队。':'你可以浏览招募，发布本局条件后再申请组队。'}}<button class="btn-secondary" @click="tab='本局条件'">填写本局条件</button></view><view v-if="activeTicket" class="notice">{{state.ticket?.status==='matched'?'已有待确认队友，请前往「我的组局」处理。':'招募中，你可以主动选择队友。'}}</view>
      <pilot-candidates :items="candidates.items" :total="candidates.total" :page="candidatePage" :recommended="recommended" :can-recommend="candidates.can_recommend" :busy="busy" :waiting="state.ticket?.status==='waiting'" :my-status="candidates.my_status" :keyword="keyword" @search="searchCandidates" @refresh="loadCandidates" @mode="setCandidateMode" @edit="tab='本局条件'" @invite="invite" @page="changePage" @skip="skipBatch"/>
    </view>
    <view v-if="tab==='我的组局'">
      <view v-if="!state.ticket" class="panel-pilot empty"><view class="aside-title">还没有本局计划</view><view class="muted">先告诉队友，你这次想怎么玩。</view><button class="btn-primary submit" @click="tab='本局条件'">填写本局条件</button></view>
      <view v-else-if="!state.squad" class="panel-pilot empty"><view class="section-num">{{state.ticket.status==='waiting'?'正在寻找队友':'本次排队已结束'}}</view><view class="aside-title">{{state.ticket.status==='waiting'?'等待符合条件的真人玩家':'准备好，再出发'}}</view><view class="muted">可以到大厅主动找队友。招募有效期为 20 分钟，过期后可重新发布。</view><view class="small">条件：{{state.ticket.profile.region}} · {{state.ticket.profile.map}} · {{state.ticket.profile.goal}} · {{state.ticket.profile.budget_min}}–{{state.ticket.profile.budget_max}} 万</view><button v-if="state.ticket.status==='waiting'" class="btn-primary submit" @click="switchTab('招募大厅')">查看推荐队友</button><button v-if="activeTicket" class="btn-secondary submit" :disabled="busy" @click="act('cancel')">取消本次排队</button><button v-else class="btn-primary submit" @click="tab='本局条件'">重新填写</button></view>
      <view v-else class="layout"><view><view class="panel-pilot"><view class="section-num">{{statusLabel}}</view><view class="aside-title">先确认约定，再进游戏。</view><view v-if="state.squad.status==='proposed'" class="warning">剩余 {{confirmRemaining}} 秒，请双方确认。超时释放名额，保留排队进度。</view><view class="members"><view v-for="m in state.squad.members" :key="m.id" class="member"><view class="avatar-pilot">{{m.profile.nickname.slice(0,1)}}</view><b>{{m.profile.nickname}}{{m.is_me?'（我）':''}}</b><view class="muted">{{ranks[m.profile.rank-1]}} · {{skills[m.profile.skill-1]}}</view><view class="small">{{m.profile.goal}} · {{m.profile.budget_min}}–{{m.profile.budget_max}} 万<br/>{{m.profile.voice}} · 自评</view><view class="status-text">{{m.confirmed?'✓ 已确认':'等待确认'}}</view><view v-if="['ready','done'].includes(state.squad.status)">游戏 ID：{{m.profile.game_id}}</view></view></view>
      <view class="compatibility"><view v-for="check in state.squad.assessment?.checks" :key="check.label">{{check.ok?'✓':'△ 不满足：'}} {{check.label}}</view></view><view v-for="w in state.squad.agreement.warnings" :key="w" class="warning">△ {{w}}，确认前请双方明确接受。</view>
      <view class="agreement"><b>本局约定</b><view>目标：{{state.squad.agreement.goal}}</view><view>共同预算：{{state.squad.agreement.budget_min<=state.squad.agreement.budget_max ? state.squad.agreement.budget_min+'–'+state.squad.agreement.budget_max+' 万 / 人':'暂无交集，需在游戏前自行协商'}}</view><view>{{state.squad.members[0].profile.region}} · {{state.squad.members[0].profile.map}} · {{state.squad.members[0].profile.difficulty}} · {{state.squad.members[0].profile.slot}}</view></view><view class="small">{{state.squad.agreement.scope}}</view>
      <button v-if="state.squad.status==='proposed'" class="btn-primary submit" :disabled="busy || myMember.confirmed" @click="act('confirm')">{{myMember.confirmed?'你已确认，等待队友':'我已看清条件并接受本局约定'}}</button><view v-if="state.squad.status==='proposed'" class="reject-box"><label>不合适？请选择原因<picker :range="rejectReasons.map(r=>r.label)" :value="rejectIndex" @change="rejectIndex=Number($event.detail.value)"><view class="select">{{rejectReasons[rejectIndex].label}} ⌄</view></picker></label><button class="btn-secondary submit" :disabled="busy" @click="rejectProposal">婉拒并继续找 · 原因不向队友公开</button></view><button v-if="['proposed','ready'].includes(state.squad.status) && !state.squad.feedback_submitted" class="btn-secondary submit" :disabled="busy" @click="cancelSquad">取消组局</button><button v-if="['done','cancelled'].includes(state.squad.status) || state.squad.feedback_submitted" class="btn-primary submit" @click="tab='本局条件'">发起下一局</button>
      </view></view>
      <view class="panel-pilot" v-if="['ready','done'].includes(state.squad.status)"><text class="eyebrow">局后独立反馈</text><view class="aside-title">下次还想一起玩吗？</view><view v-if="state.squad.feedback_submitted" class="notice">反馈已保存，谢谢你帮助我们改善匹配。</view><view v-else><label>是否实际一起游玩？<view class="choices"><button :class="{chosen:review.played}" @click="review.played=true">已游玩</button><button :class="{chosen:!review.played}" @click="review.played=false">未游玩</button></view></label><view class="small" v-if="!review.played">告诉我们没能一起玩的原因，帮助下次找到更合适的队友。</view><label v-for="item in reviewFields" :key="item.key">{{item.label}}<switch :checked="review[item.key]" @change="review[item.key]=$event.detail.value" color="#286952"/></label><label>愿意再次组队？<view class="choices"><button v-for="o in againOptions" :key="o.value" :class="{chosen:review.again===o.value}" @click="review.again=o.value">{{o.label}}</button></view></label><label>原因（可选）<textarea v-model="review.reason" maxlength="300" placeholder="区分水平差距、目标分歧与单纯输了比赛"/></label><button class="btn-primary submit" :disabled="busy || !review.again" @click="act('feedback',review)">提交本局反馈</button></view></view>
      </view>
    </view>
    <view class="footer">三角 · 找到合拍的队友</view>
  </view>
</template>
<script setup>
import { ref, reactive, computed, watch } from 'vue'
import { onShow, onHide, onUnload } from '@dcloudio/uni-app'
import PilotCandidates from '../../components/pilot-candidates.vue'
import { API_BASE } from '../../config.js'
import { loadPreferences, savePreferences, pickPreferences } from '../../utils/pilot-preferences.js'
const tab=ref('本局条件'), busy=ref(false), error=ref(''), state=ref({}), config=ref({})
const candidates=ref({items:[],total:0,can_recommend:false}), recommended=ref(false), keyword=ref(''), candidatePage=ref(0), rejectIndex=ref(0), clock=ref(Date.now())
const rejectReasons=[{value:'goal',label:'目标不同'},{value:'budget',label:'装备预算不合适'},{value:'skill',label:'实力预期不符'},{value:'communication',label:'沟通方式不合适'},{value:'time',label:'时间安排变化'},{value:'other',label:'其他原因'}]
let serverOffset=0, refreshing=false, tick=0, candidateLoadId=0
let timer=null, token=uni.getStorageSync('pilot-token')||''
const ranks=['青铜','白银','黄金','白金','钻石','黑鹰','巅峰'], skills=['1 · 初学','2 · 入门','3 · 熟练','4 · 进阶','5 · 高水平'], gaps=['仅同档','可相差 1 档','可相差 2 档','可相差 3 档','均可']
const skillNotes=['仍在学习地图与基础操作','能独立搜集，交战需要帮助','能报点、撤退与配合完成常规任务','能处理复杂交战并指挥协同','熟悉所选地图并能稳定处理高强度交战']
const goals=['任务','搜集撤离','主动交战'], goalNotes={'任务':'优先完成任务，交战服务于任务。','搜集撤离':'优先收益与撤离，减少不必要交战。','主动交战':'主动寻找战斗，接受更高损失。'}
const fields=[{key:'region',label:'区服',values:['NA','EU','SEA','OCE','ME']},{key:'platform',label:'平台',values:['PC','Console','Mobile']},{key:'language',label:'沟通语言',values:['中文','English','日本語']},{key:'map',label:'地图',values:['零号大坝','长弓溪谷','巴克什']},{key:'difficulty',label:'难度',values:['简单','普通']},{key:'voice',label:'语音方式',values:['开麦','听指挥与标记']},{key:'slot',label:'开局时段',values:['现在起一小时','今天晚间']}]
const localPreferences=loadPreferences(uni)
let hasLocalDraft=localPreferences.found
const form=reactive(localPreferences.values)
const localSaveFailed=ref(false)
watch(form,value=>{hasLocalDraft=true;localSaveFailed.value=!savePreferences(uni,value)},{deep:true,flush:'sync'})
const review=reactive({played:true,again:'',goal_met:false,budget_met:false,skill_met:false,reason:''})
const reviewFields=[{key:'goal_met',label:'实际遵守了本局目标'},{key:'budget_met',label:'实际装备投入符合约定'},{key:'skill_met',label:'实际水平在可接受范围内'}], againOptions=[{value:'yes',label:'愿意'},{value:'unsure',label:'不确定'},{value:'no',label:'不愿意'}]
const activeTicket=computed(()=>['waiting','matched'].includes(state.value.ticket?.status))
const myMember=computed(()=>state.value.squad?.members.find(m=>m.is_me)||{})
const statusLabel=computed(()=>({proposed:'队友已找到 · 等待双方确认',ready:'双方已确认 · 在游戏内添加队友',done:'本次组局已完成',cancelled:'本次组局已取消'}[state.value.squad?.status]))
const confirmRemaining=computed(()=>Math.max(0,Math.ceil((Date.parse(state.value.squad?.deadline||'')-(clock.value+serverOffset))/1000))||0)
async function request(path,data){return new Promise((resolve,reject)=>uni.request({url:API_BASE+'/pilot/'+path,method:data===undefined?'GET':'POST',data,header:{Authorization:'Bearer '+token},success:r=>{if(r.statusCode>=400){let d=r.data.detail;reject(new Error(typeof d==='string'?d:'输入有误，请检查昵称、预算及必填项'))}else resolve(r.data)},fail:()=>reject(new Error('连接暂时中断，请稍后重试'))}))}
function applyState(value){clock.value=Date.now();state.value=value;config.value=value.config;if(value.server_now)serverOffset=Date.parse(value.server_now)-Date.now()}
async function refresh(){if(refreshing)return;refreshing=true;try{applyState(await request('state'));error.value=''}catch(e){error.value=e.message}finally{refreshing=false}}
async function loadCandidates(){const id=++candidateLoadId;try{const value=await request('candidates?recommended='+recommended.value+'&page='+candidatePage.value+'&query='+encodeURIComponent(keyword.value));if(id===candidateLoadId)candidates.value=value}catch(e){if(id===candidateLoadId)error.value=e.message}}
function setCandidateMode(value){recommended.value=value;candidatePage.value=0;loadCandidates()}
function searchCandidates(value){keyword.value=value;candidatePage.value=0;loadCandidates()}
function changePage(value){candidatePage.value=value;loadCandidates()}
async function invite(id){busy.value=true;error.value='';try{applyState(await request('invite',{candidate_id:id}));tab.value='我的组局'}catch(e){error.value=e.message;await loadCandidates()}finally{busy.value=false}}
async function skipBatch(){busy.value=true;error.value='';try{await request('skip',{candidate_ids:candidates.value.items.map(c=>c.id)});candidatePage.value=0;await loadCandidates()}catch(e){error.value=e.message}finally{busy.value=false}}
async function switchTab(t){tab.value=t;await refresh();if(t==='招募大厅')await loadCandidates()}
async function join(){busy.value=true;error.value='';try{if(!form.nickname.trim()||!form.game_id.trim())throw new Error('请填写昵称和游戏 ID');if(form.budget_min>form.budget_max)throw new Error('预算下限不能高于上限');applyState(await request('join',{...form}));Object.assign(review,{played:true,again:'',goal_met:false,budget_met:false,skill_met:false,reason:''});tab.value=state.value.squad?'我的组局':form.discovery==='browse'?'招募大厅':'我的组局';if(tab.value==='招募大厅')await loadCandidates()}catch(e){error.value=e.message}finally{busy.value=false}}
async function act(action,data={}){busy.value=true;error.value='';try{applyState(await request(action,{...data,squad_id:state.value.squad?.id}));if(action==='reject'){tab.value='招募大厅';candidatePage.value=0;await loadCandidates()}}catch(e){error.value=e.message}finally{busy.value=false}}
function rejectProposal(){act('reject',{reason:rejectReasons[rejectIndex.value].value})}
function cancelSquad(){uni.showModal({title:'取消本次组局？',content:'你将退出本局，对方可以继续寻找队友。',success:r=>{if(r.confirm)act('cancel')}})}
async function init(){try{if(!token){const r=await request('participants',{});token=r.token;uni.setStorageSync('pilot-token',token)}await refresh();if(!hasLocalDraft && state.value.ticket?.profile)Object.assign(form,pickPreferences(state.value.ticket.profile))}catch(e){error.value=e.message}clearInterval(timer);timer=setInterval(async()=>{clock.value=Date.now();if(!busy.value&&++tick%4===0){await refresh();if(tab.value==='招募大厅')await loadCandidates()}},1000)}

onShow(init);onHide(()=>clearInterval(timer));onUnload(()=>clearInterval(timer))
</script>
